package com.tehang.enterpriserisk.api;
import com.tehang.enterpriserisk.service.AuthService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.constraints.NotBlank; import java.util.Map; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService auth; public AuthController(AuthService a){auth=a;} @PostMapping("/login") public Map<String,Object> login(@RequestBody Login r){return auth.login(r.account(),r.password());} @PostMapping("/change-password") public void change(@RequestBody Password r,HttpServletRequest q){auth.changePassword((String)q.getAttribute("account"),r.password());} @PostMapping("/logout") public void logout(){} public record Login(@NotBlank String account,@NotBlank String password){} public record Password(@NotBlank String password){} }
